USE fahizhub;
CREATE TABLE IF NOT EXISTS uploaded_files (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,kind ENUM('project_image','certificate','cv') NOT NULL,entity_id BIGINT UNSIGNED NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(255) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes INT UNSIGNED NOT NULL,url VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_upload_kind_entity(kind,entity_id));
CREATE TABLE IF NOT EXISTS grading_rules (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,label VARCHAR(20) NOT NULL UNIQUE,min_mark DECIMAL(5,2) NULL,max_mark DECIMAL(5,2) NULL,grade_point DECIMAL(4,2) NOT NULL,display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS grade_entries (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,course_name VARCHAR(190) NOT NULL,credit DECIMAL(4,2) NOT NULL,grade_label VARCHAR(20),grade_point DECIMAL(4,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS unavailable_dates (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,date DATE NOT NULL UNIQUE,reason VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blocked_slots (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,start_time_utc DATETIME NOT NULL,end_time_utc DATETIME NOT NULL,reason VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_blocked_times(start_time_utc,end_time_utc));
CREATE TABLE IF NOT EXISTS app_settings (setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS email_log (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,recipient VARCHAR(190) NOT NULL,subject VARCHAR(255) NOT NULL,status ENUM('sent','failed','skipped') NOT NULL,error_message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_email_status_date(status,created_at));
CREATE TABLE IF NOT EXISTS public_ai_usage (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,visitor_hash CHAR(64) NOT NULL,request_date DATE NOT NULL,request_count INT UNSIGNED NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_ai_usage_day(visitor_hash,request_date));
